parameters:
name: string; fields: readonly ResourceFieldIR[]; options: {
        model?: string;
        aliases?: readonly ResourceAliasIR[];
        source?: IRSourceRef;
    }

resource: string; shape: CollectionShape; options: {
    model?: string;
    type?: TypeIR;
  }

{
    schemaMapper = new ContractSchemaMapper(),
    actionGenerator = new ContractActionGenerator(),
    codeBuilder = new ContractCodeBuilder(),
    responseActionBuilder = new ResponseActionBuilder(new ResponseSchemaMapper())
}: Partial<ContractGeneratorDependencies>

deps: {
        readonly generator: IGenerator<TInput, TTargetNode>;
        readonly formatter: IFormatter<TTargetNode>;
        readonly emitter: IEmitter<TTargetNode>;
        readonly writer: IWriter;
        readonly config: EngineConfig;
    }; input: TInput; logger: (message: string) => void

parts: ResourceRelationLoadTargetParts; visitor: {
    readonly path_only: (value: Extract<ResourceRelationLoadTargetParts, { readonly kind: 'path_only' }>) => R;
    readonly path_with_selection: (value: Extract<ResourceRelationLoadTargetParts, { readonly kind: 'path_with_selection' }>) => R;
    readonly invalid: (value: Extract<ResourceRelationLoadTargetParts, { readonly kind: 'invalid' }>) => R;
  }

selection: ResourceRelationLoadSelectionParts; visitor: {
    readonly properties: (value: Extract<ResourceRelationLoadSelectionParts, { readonly kind: 'properties' }>) => R;
    readonly invalid: (value: Extract<ResourceRelationLoadSelectionParts, { readonly kind: 'invalid' }>) => R;
  }

resolution: SemanticResolution; visitor: {
    scalar: (value: ScalarSemanticResolution) => T;
    model: (value: ModelSemanticResolution) => T;
    resource: (value: ResourceSemanticResolution) => T;
    object: (value: ObjectSemanticResolution) => T;
    query_projection: (value: QueryProjectionSemanticResolution) => T;
    indeterminate: (value: IndeterminateSemanticResolution) => T;
  }

node: SemanticNode; visitor: {
    scalar: (value: SemanticNodeScalar) => T;
    model: (value: SemanticNodeModel) => T;
    resource: (value: SemanticNodeResource) => T;
    object: (value: SemanticNodeObject) => T;
    query_projection: (value: SemanticNodeProjection) => T;
    indeterminate: (value: SemanticNodeIndeterminate) => T;
  }
